INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT136-S2-Q3$batch13$, 136, 2, 3, $batch13$Strengthen$batch13$, $batch13$Lawyer: Juries are traditionally given their instructions in convoluted, legalistic language. The verbiage is intended to make the instructions more precise, but greater precision is of little use if most jurors have difficulty understanding the instructions. Since it is more important for jurors to have a basic but adequate understanding of their role than it is for the details of that role to be precisely specified, jury instructions should be formulated in simple, easily comprehensible language.$batch13$, $batch13$Each of the following, if true, strengthens the lawyer's argument except:$batch13$, $batch13$D$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=136 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT136-S2-Q3$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$Most jurors are less likely to understand instructions given in convoluted, legalistic language than instructions given in simple, easily comprehensible language.$batch13$, $batch13$Strengthens$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT136-S2-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$Most jurors do not have an adequate understanding of their role after being given jury instructions in convoluted, legalistic language.$batch13$, $batch13$Strengthens$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT136-S2-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$Jury instructions formulated in simple, easily comprehensible language can adequately describe the role of the jurors.$batch13$, $batch13$Strengthens$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT136-S2-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$The details of the role of the jurors cannot be specified with complete precision in simple, easily comprehensible language.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT136-S2-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$Jurors do not need to know the precise details of their role in order to have an adequate understanding of that role.$batch13$, $batch13$Strengthens$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT136-S2-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT136-S2-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Jury instructions should be in simple, easily understood language.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Legalistic language aims at precision, but precision is of little use if jurors can't understand the instructions. A basic, adequate understanding of their role matters more than precise detail.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$This is an EXCEPT question. Four choices support the switch: legalistic language confuses jurors, simple language works, or precision isn't needed. The answer adds nothing in favor.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Find the choice that doesn't help the case for simple language.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT136-S2-Q3$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Jurors understand simple language better, which is the argument's main concern.$batch13$), ($batch13$B$batch13$, $batch13$The current instructions fail at the goal the lawyer cares about.$batch13$), ($batch13$C$batch13$, $batch13$Simple language can do the job.$batch13$), ($batch13$D$batch13$, $batch13$This admits simple language loses some precision. The lawyer already accepts that trade, so it adds no support, and on its own it's a point against simple language.$batch13$), ($batch13$E$batch13$, $batch13$Jurors can understand their role without the precise details, so the precision lost costs little.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT136-S2-Q3$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
